INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BAILEY','primary text','Alice A. Bailey, A Treatise on the Seven Rays; Initiation, Human and Solar','Theosophical'),
 ('SRC_STEINER','primary text','Rudolf Steiner, An Outline of Esoteric Science (Die Geheimwissenschaft im Umriss)','Anthroposophy'),
 ('SRC_SPIRITUALISM','secondary scholarship','19th-century Spiritualist literature (Andrew Jackson Davis, The Harmonial Philosophy; and related)','Spiritualist')
INSERT INTO _e VALUES
 ('ENT_THE_MAITREYA','Maitreya (the Christ / the World Teacher)','Theosophical','World teacher','Spirit','world teaching; the love-wisdom principle; the office of the Christ; spiritual education of humanity','B','In Bailey''s Theosophy, Maitreya is the Christ and World Teacher who heads the teaching department of the Spiritual Hierarchy under Sanat Kumara; fuses the Buddhist future-buddha Maitreya with the Theosophical office of ''the Christ.'''),
 ('ENT_THE_SEVEN_RAYS','The Seven Rays','Theosophical','Cosmic being','Spirit','seven streams of divine energy; will, love-wisdom, active intelligence, harmony, science, devotion, ceremonial order','B','The seven differentiated streams of divine energy (the Ray Lords and their qualities) that condition all souls and along which the Masters serve; modeled as one collective rather than seven entities.'),
 ('ENT_THE_SOLAR_ANGEL','The Solar Angel (Angel of the Presence)','Theosophical','Cosmic being','Spirit','the higher self / soul; mediation between Monad and personality; egoic consciousness','B','In Bailey''s esoteric psychology the soul/higher-self mediator overshadowing the human personality, called the ''Angel of the Presence''; an adaptation of older soul-guardian concepts.'),
 ('ENT_THE_SHAMBALLA','Shamballa (the City of God)','Theosophical','cosmological realm','Cosmological realm','spiritual planetary centre; seat of the planetary Logos; the will-to-good','B','The highest of the three planetary spiritual centres in Bailey''s cosmology, the ''City of God'' where Sanat Kumara dwells; an adaptation of the Tibetan mythic kingdom of Shambhala.'),
 ('ENT_THE_MANU','The Manu','Theosophical','Spiritual office','Spirit','will and government department of the Hierarchy; racial and political evolution; first-ray administration','B','The Master heading the will/government (first-ray) department of the Spiritual Hierarchy, paralleling the Christ (teaching) and the Maha Chohan (civilization); an adaptation of the Hindu Manu.'),
 ('ENT_THE_BUDDHAS_ACTIVITY','The Buddhas of Activity','Theosophical','Collective','Spirit','assistance to Sanat Kumara; transmission of cosmic energies; planetary administration at Shamballa','B','A collective of three exalted beings who assist Sanat Kumara at Shamballa, mediating cosmic energies to the planet; a Bailey-era elaboration of the Shamballa hierarchy.'),
 ('ENT_THE_MASTER_JESUS','The Master Jesus','Theosophical','Ascended master','Spirit','sixth ray of devotion and idealism; guidance of Christianity and the churches; discipleship','B','In Bailey''s Theosophy a sixth-ray Master distinct from the Christ (Maitreya): the disciple-vehicle whose body ''the Christ'' overshadowed, who now oversees the Christian churches; explicitly separate from the canonical Jesus Christ.'),
 ('ENT_THE_SAINT_GERMAIN','The Master Saint Germain (Rakoczi)','Theosophical','Ascended master','Spirit','seventh ray of ceremonial order and magic; civilization and culture; ritual and organization','B','The seventh-ray Chohan of ceremonial order and magic (the Master R. / Rakoczi); an adaptation built on the historical 18th-century Count of St Germain, recast as an ascended Master.'),
 ('ENT_THE_HILARION','The Master Hilarion','Theosophical','Ascended master','Spirit','fifth ray of concrete knowledge and science; revelation of truth; the new science','B','The fifth-ray Chohan of concrete knowledge and science in Bailey''s Theosophy; the name adapted from the early Christian ascetic St Hilarion.'),
 ('ENT_THE_SERAPIS_BEY','The Master Serapis Bey','Theosophical','Ascended master','Spirit','fourth ray of harmony through conflict; beauty and the arts; aspiration and discipline','B','The fourth-ray Chohan of harmony-through-conflict in Bailey''s system; a Master distinct from the Greco-Egyptian deity Serapis, the name being borrowed from it.'),
 ('ENT_ANT_AHRIMAN','Ahriman','Anthroposophy','Adversarial being','Adversarial being','materialism; mechanization; coldness; intellectual hardening; spiritual deadening','B','In Steiner''s cosmology the cold, contracting adversary-being who drags humanity into materialism and denial of the spirit; the name is adapted from Zoroastrian Ahriman (Angra Mainyu) but the being is a distinct Anthroposophical re-conception.'),
 ('ENT_ANT_LUCIFER','Lucifer (Anthroposophical)','Anthroposophy','Adversarial being','Adversarial being','pride; egotism; false spirituality; fantasy; inflation; illusion','B','Steiner''s warm, expanding adversary-being of pride, fantasy, and false/inflated spirituality, the polar opposite of Ahriman; a deliberate re-conception that shares only the name with the Christian fallen-angel Lucifer.'),
 ('ENT_ANT_ASURAS','The Asuras','Anthroposophy','Adversarial collective','Adversarial collective','spirit-self corruption; egoity; destruction of the I; the most dangerous temptation','B','In Steiner''s teaching the third and most dangerous class of adversary-beings, attacking the human spirit-self (the ''I''); the name is borrowed from the Indian asuras but designates a distinct Anthroposophical class.'),
 ('ENT_ANT_SORAT','Sorat','Anthroposophy','Eschatological adversary','Eschatological adversary','anti-Christ force; the Sun-Demon; the Beast; the number 666; opposition to the Sun-Being','B','Steiner''s Sun-Demon and Beast/Antichrist being, adversary of the Sun-Christ and associated with the number 666; named from the Agrippan solar spirit Sorath, distinct from the Lucifer-Ahriman-Asuras polarity.'),
 ('ENT_ANT_REPRESENTATIVE','The Representative of Humanity','Anthroposophy','Cosmic being','Eschatological savior','the Christ; the Sun-Being; balance; equilibrium between Lucifer and Ahriman; archetypal humanity','B','Steiner''s figure of the Christ / Sun-Being who holds the central balance between the upward pull of Lucifer and the downward pull of Ahriman; an Anthroposophical interpretation of the Christ identified with Jesus Christ.'),
 ('ENT_ANT_ADVERSARIES','The Threefold Adversaries','Anthroposophy','Adversarial collective','Adversarial collective','adversary powers; threefold opposition; the Lucifer-Ahriman-Asuras grouping','B','Collective grouping the three classes of adversary-being in Steiner''s cosmology (Lucifer, Ahriman, and the Asuras), whose opposed pulls human spiritual development must learn to balance.'),
 ('ENT_SPI_SUMMERLAND','The Summerland','Spiritualist','cosmological realm','Cosmological realm','afterlife; the spirit world; rest; progress of the soul; the pleasant abode of the dead','C','The Spiritualist afterlife or spirit world, conceived as a pleasant realm of rest and ongoing moral and spiritual progress; details vary widely across 19th-century Spiritualist sources.'),
 ('ENT_SPI_SPIRIT_GUIDES','Spirit Guides','Spiritualist','Spirit collective','Spirit collective','discarnate guidance; mediumship; communication with the living; spiritual instruction','C','The class of discarnate guiding spirits believed to communicate through and assist mediums; a practice-defined category rather than a fixed roster of named beings.'),
 ('ENT_SPI_DOORKEEPER','The Doorkeeper','Spiritualist','Guardian spirit','Protective spirit','protection; gatekeeping; control of spirit access; guardianship of the medium','C','A protective guardian spirit in Spiritualist practice who controls which spirits are permitted to approach or communicate through a medium; a role-type whose identity varies by medium.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_THE_MAITREYA','SRC_BAILEY','In Bailey''s Theosophy, Maitreya is the Christ and World Teacher who heads the teaching department of the Spiritual Hierarchy under Sanat Kumara; fuses the Buddhist future-buddha Maitreya with the Theosophical office of ''the Christ.''','primary text attestation'),
 ('ENT_THE_SEVEN_RAYS','SRC_BAILEY','The seven differentiated streams of divine energy (the Ray Lords and their qualities) that condition all souls and along which the Masters serve; modeled as one collective rather than seven entities.','primary text attestation'),
 ('ENT_THE_SOLAR_ANGEL','SRC_BAILEY','In Bailey''s esoteric psychology the soul/higher-self mediator overshadowing the human personality, called the ''Angel of the Presence''; an adaptation of older soul-guardian concepts.','primary text attestation'),
 ('ENT_THE_SHAMBALLA','SRC_BAILEY','The highest of the three planetary spiritual centres in Bailey''s cosmology, the ''City of God'' where Sanat Kumara dwells; an adaptation of the Tibetan mythic kingdom of Shambhala.','primary text attestation'),
 ('ENT_THE_MANU','SRC_BAILEY','The Master heading the will/government (first-ray) department of the Spiritual Hierarchy, paralleling the Christ (teaching) and the Maha Chohan (civilization); an adaptation of the Hindu Manu.','primary text attestation'),
 ('ENT_THE_BUDDHAS_ACTIVITY','SRC_BAILEY','A collective of three exalted beings who assist Sanat Kumara at Shamballa, mediating cosmic energies to the planet; a Bailey-era elaboration of the Shamballa hierarchy.','primary text attestation'),
 ('ENT_THE_MASTER_JESUS','SRC_BAILEY','In Bailey''s Theosophy a sixth-ray Master distinct from the Christ (Maitreya): the disciple-vehicle whose body ''the Christ'' overshadowed, who now oversees the Christian churches; explicitly separate from the canonical Jesus Christ.','primary text attestation'),
 ('ENT_THE_SAINT_GERMAIN','SRC_BAILEY','The seventh-ray Chohan of ceremonial order and magic (the Master R. / Rakoczi); an adaptation built on the historical 18th-century Count of St Germain, recast as an ascended Master.','primary text attestation'),
 ('ENT_THE_HILARION','SRC_BAILEY','The fifth-ray Chohan of concrete knowledge and science in Bailey''s Theosophy; the name adapted from the early Christian ascetic St Hilarion.','primary text attestation'),
 ('ENT_THE_SERAPIS_BEY','SRC_BAILEY','The fourth-ray Chohan of harmony-through-conflict in Bailey''s system; a Master distinct from the Greco-Egyptian deity Serapis, the name being borrowed from it.','primary text attestation'),
 ('ENT_ANT_AHRIMAN','SRC_STEINER','In Steiner''s cosmology the cold, contracting adversary-being who drags humanity into materialism and denial of the spirit; the name is adapted from Zoroastrian Ahriman (Angra Mainyu) but the being is a distinct Anthroposophical re-conception.','primary text attestation'),
 ('ENT_ANT_LUCIFER','SRC_STEINER','Steiner''s warm, expanding adversary-being of pride, fantasy, and false/inflated spirituality, the polar opposite of Ahriman; a deliberate re-conception that shares only the name with the Christian fallen-angel Lucifer.','primary text attestation'),
 ('ENT_ANT_ASURAS','SRC_STEINER','In Steiner''s teaching the third and most dangerous class of adversary-beings, attacking the human spirit-self (the ''I''); the name is borrowed from the Indian asuras but designates a distinct Anthroposophical class.','primary text attestation'),
 ('ENT_ANT_SORAT','SRC_STEINER','Steiner''s Sun-Demon and Beast/Antichrist being, adversary of the Sun-Christ and associated with the number 666; named from the Agrippan solar spirit Sorath, distinct from the Lucifer-Ahriman-Asuras polarity.','primary text attestation'),
 ('ENT_ANT_REPRESENTATIVE','SRC_STEINER','Steiner''s figure of the Christ / Sun-Being who holds the central balance between the upward pull of Lucifer and the downward pull of Ahriman; an Anthroposophical interpretation of the Christ identified with Jesus Christ.','primary text attestation'),
 ('ENT_ANT_ADVERSARIES','SRC_STEINER','Collective grouping the three classes of adversary-being in Steiner''s cosmology (Lucifer, Ahriman, and the Asuras), whose opposed pulls human spiritual development must learn to balance.','primary text attestation'),
 ('ENT_SPI_SUMMERLAND','SRC_SPIRITUALISM','The Spiritualist afterlife or spirit world, conceived as a pleasant realm of rest and ongoing moral and spiritual progress; details vary widely across 19th-century Spiritualist sources.','scholarly attestation'),
 ('ENT_SPI_SPIRIT_GUIDES','SRC_SPIRITUALISM','The class of discarnate guiding spirits believed to communicate through and assist mediums; a practice-defined category rather than a fixed roster of named beings.','scholarly attestation'),
 ('ENT_SPI_DOORKEEPER','SRC_SPIRITUALISM','A protective guardian spirit in Spiritualist practice who controls which spirits are permitted to approach or communicate through a medium; a role-type whose identity varies by medium.','scholarly attestation');
