INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_THE_MAITREYA','member_of','ENT_THE_HIERARCHY','high','Maitreya (the Christ/World Teacher) heads the teaching department of the Spiritual Hierarchy under Sanat Kumara.'),
 ('ENT_THE_MANU','member_of','ENT_THE_HIERARCHY','high','The Manu heads the will/government department of the Spiritual Hierarchy.'),
 ('ENT_THE_BUDDHAS_ACTIVITY','member_of','ENT_THE_HIERARCHY','high','The Buddhas of Activity belong to the planetary hierarchy at Shamballa, assisting Sanat Kumara.'),
 ('ENT_THE_SOLAR_ANGEL','member_of','ENT_THE_HIERARCHY','low','The Solar Angel is a soul-order mediator within the broader Theosophical hierarchy.'),
 ('ENT_THE_MASTER_JESUS','member_of','ENT_REC_MAHATMAS','high','The Master Jesus is one of the named Masters of Wisdom (sixth-ray).'),
 ('ENT_THE_SAINT_GERMAIN','member_of','ENT_REC_MAHATMAS','high','The Master Saint Germain (Rakoczi) is the seventh-ray Chohan among the Masters of Wisdom.'),
 ('ENT_THE_HILARION','member_of','ENT_REC_MAHATMAS','high','The Master Hilarion is the fifth-ray Chohan among the Masters of Wisdom.'),
 ('ENT_THE_SERAPIS_BEY','member_of','ENT_REC_MAHATMAS','high','The Master Serapis Bey is the fourth-ray Chohan among the Masters of Wisdom.'),
 ('ENT_THE_SANAT_KUMARA','dwells_in','ENT_THE_SHAMBALLA','high','Sanat Kumara, the Lord of the World, dwells at Shamballa, the highest planetary spiritual centre.'),
 ('ENT_THE_MAITREYA','aligned_with','ENT_JESUS_CHRIST','medium','Bailey''s ''the Christ'' (Maitreya) is the cosmic principle that overshadowed Jesus; a modern functional cognate of the canonical Christ.'),
 ('ENT_THE_MASTER_JESUS','aligned_with','ENT_JESUS_CHRIST','medium','The Master Jesus is the disciple-vehicle whom ''the Christ'' overshadowed; functionally linked to the canonical Jesus while held distinct.'),
 ('ENT_THE_MAITREYA','presides_over','ENT_WISDOM','medium','As the World Teacher embodying the love-wisdom principle, Maitreya presides over wisdom.'),
 ('ENT_THE_SOLAR_ANGEL','presides_over','ENT_HIDDEN_KNOWLEDGE','medium','As the soul/higher-self mediator, the Solar Angel governs access to inner esoteric knowledge.'),
 ('ENT_THE_SEVEN_RAYS','presides_over','ENT_HIDDEN_KNOWLEDGE','low','The Seven Rays are the energy qualities conditioning all esoteric structure in Bailey''s system.'),
 ('ENT_THE_HILARION','presides_over','ENT_KNOWLEDGE','medium','As fifth-ray Chohan of concrete knowledge and science, Hilarion presides over knowledge.'),
 ('ENT_THE_SAINT_GERMAIN','presides_over','ENT_MAGIC','medium','As seventh-ray Chohan of ceremonial order and magic, Saint Germain presides over magic.'),
 ('ENT_ANT_LUCIFER','member_of','ENT_ANT_ADVERSARIES','high','Lucifer is one of the three classes constituting Steiner''s threefold adversary powers.'),
 ('ENT_ANT_AHRIMAN','member_of','ENT_ANT_ADVERSARIES','high','Ahriman is one of the three classes constituting Steiner''s threefold adversary powers.'),
 ('ENT_ANT_ASURAS','member_of','ENT_ANT_ADVERSARIES','high','The Asuras are the third and most dangerous class within Steiner''s threefold adversary powers.'),
 ('ENT_ANT_AHRIMAN','reception_of','ENT_ZOR_ANGRA_MAINYU','high','Steiner adopted the name and adversarial role of his Ahriman from the Zoroastrian Angra Mainyu (Ahriman).'),
 ('ENT_ANT_LUCIFER','aligned_with','ENT_CHR_LUCIFER','medium','Steiner''s Lucifer is a re-conception named after, but not identical to, the Christian fallen-angel Lucifer.'),
 ('ENT_ANT_SORAT','aligned_with','ENT_REN_SORATH','high','Steiner''s Sun-Demon Sorat takes its name and 666 solar association from the Agrippan solar spirit Sorath.'),
 ('ENT_ANT_SORAT','aligned_with','ENT_CHR_ANTICHRIST','medium','Steiner''s Sorat functions as the Beast/Antichrist being opposing the Sun-Christ.'),
 ('ENT_ANT_REPRESENTATIVE','aligned_with','ENT_JESUS_CHRIST','high','The Representative of Humanity is Steiner''s interpretation of the Christ / Sun-Being, identified with Jesus Christ.'),
 ('ENT_ANT_REPRESENTATIVE','opposes','ENT_ANT_LUCIFER','high','The Representative of Humanity holds the central balance against the upward, inflating pull of Lucifer.'),
 ('ENT_ANT_REPRESENTATIVE','opposes','ENT_ANT_AHRIMAN','high','The Representative of Humanity holds the central balance against the downward, materializing pull of Ahriman.'),
 ('ENT_ANT_AHRIMAN','presides_over','ENT_DECEPTION','medium','Ahriman governs the deceptive lure of pure materialism and the reduction of the spiritual to the mechanical.'),
 ('ENT_ANT_SORAT','presides_over','ENT_DESTRUCTION','medium','Sorat as the Sun-Demon and Beast embodies an annihilating, anti-Christ destructive force.'),
 ('ENT_ANT_LUCIFER','presides_over','ENT_DECEPTION','medium','Lucifer governs the deceptive temptations of pride, illusion, and false/inflated spirituality.'),
 ('ENT_SPI_DOORKEEPER','member_of','ENT_SPI_SPIRIT_GUIDES','high','The Doorkeeper is a specialized protective role within the broader class of spirit guides.'),
 ('ENT_SPI_SPIRIT_GUIDES','dwells_in','ENT_SPI_SUMMERLAND','medium','Spirit guides are discarnate dead understood to abide in the Summerland spirit world between communications.'),
 ('ENT_SPI_DOORKEEPER','presides_over','ENT_PROTECTION','medium','The Doorkeeper''s defining function is protective gatekeeping over which spirits may approach a medium.'),
 ('ENT_SPI_SPIRIT_GUIDES','presides_over','ENT_REVELATION','medium','Spirit guides function to disclose messages and knowledge from the dead to the living through mediums.'),
 ('ENT_SPI_SUMMERLAND','presides_over','ENT_DEATH','medium','The Summerland is the Spiritualist realm of the dead, the post-mortem destination of the soul.');
INSERT INTO entity_relationships(subject_entity_id,relationship_type,object_entity_id,confidence,rationale,source_id,review_status)
